package output
EOF
cat > internal/cli/cli_test.go <<'EOF'
package cli

import (
	\"bytes\"
	\"testing\"
)

func TestRunReturnsSuccessForInitialCommand(t *testing.T) {
	var stdout, stderr bytes.Buffer
	if got := Run(nil, &stdout, &stderr); got "'!= 0 {
		t.Fatalf("Run(nil) = %d, want 0", got)
	}
	if got := stdout.Len(); got != 0 {
		t.Fatalf("stdout length = %d, want 0", got)
	}
	if got := stderr.Len(); got != 0 {
		t.Fatalf("stderr length = %d, want 0", got)
	}
}
EOF
cat > cmd/dupfind/main_test.go <<'"'EOF'
package main

import (
	\"os/exec\"
	\"path/filepath\"
	\"testing\"
)

func TestExecutablePackageBuilds(t *testing.T) {
	binary := filepath.Join(t.TempDir(), \"dupfind\")
	cmd := exec.Command(\"go\", \"build\", \"-o\", binary, \"./cmd/dupfind\")
	if output, err := cmd.CombinedOutput(); err "'!= nil {
		t.Fatalf("go build ./cmd/dupfind failed: %v'"\\n%s\", err, output)
	}
}

func TestApplicationPackagesCompileTogether(t *testing.T) {
	cmd := exec.Command(\"go\", \"test\", \"./...\")
	if output, err := cmd.CombinedOutput(); err "'!= nil {
		t.Fatalf("go test ./... failed: %v'"\\n%s\", err, output)
	}
}
EOF
gofmt -w cmd internal
go build ./cmd/dupfind && go test ./..."

/bin/bash -lc "cat > cmd/dupfind/main_test.go <<'EOF'
package main

import (
	\"os/exec\"
	\"path/filepath\"
	\"sort\"
	\"strings\"
	\"testing\"
)

func TestExecutablePackageBuilds(t *testing.T) {
	binary := filepath.Join(t.TempDir(), \"dupfind\")
	cmd := exec.Command(\"go\", \"build\", \"-o\", binary, \"./cmd/dupfind\")
	if output, err := cmd.CombinedOutput(); err "'!= nil {
		t.Fatalf("go build ./cmd/dupfind failed: %v'"\\n%s\", err, output)
	}
}

func TestApplicationPackageLayout(t *testing.T) {
	cmd := exec.Command(\"go\", \"list\", \"-f\", \"{{.ImportPath}}\", \"./...\")
	output, err := cmd.Output()
	if err "'!= nil {
		t.Fatalf("go list ./... failed: %v", err)
	}
	got := strings.Fields(string(output))
	sort.Strings(got)
	want := []string{
		"dupfind/cmd/dupfind",
		"dupfind/internal/cli",
		"dupfind/internal/output",
		"dupfind/internal/scan",
	}
	if len(got) != len(want) {
		t.Fatalf("package count = %d, want %d: %v", len(got), len(want), got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("package %d = %q, want %q", i, got[i], want[i])
		}
	}
}
EOF
gofmt -w cmd/dupfind/main_test.go
go build ./cmd/dupfind && go test ./...'

